#include <bits/stdc++.h>
using namespace std;

int pw6[6];
int need[5], price[5], have;
struct Plan { vector<pair<int, int>> items; int price; };
vector<Plan> plans;
int memo[7776];

int solve(int state) {
    int &res = memo[state];
    if (res != -1) return res;

    // 解码：各商品剩余需求
    int rem[5], t = state;
    bool allZero = true;
    for (int i = 0; i < have; i++) {
        rem[i] = t % 6; t /= 6;
        if (rem[i]) allZero = false;
    }
    if (allZero) return res = 0;

    // 兜底：剩余全部按原价买
    res = 0;
    for (int i = 0; i < have; i++) res += rem[i] * price[i];

    // 枚举促销方案；方案可重复购买，所以每个都要参与比较
    for (const Plan &pl : plans) {
        int ns = state;
        bool ok = true;
        for (auto &it : pl.items) {
            if (rem[it.first] < it.second) { ok = false; break; }
            ns -= it.second * pw6[it.first];
        }
        if (!ok) continue;                  // 会买多，不允许
        res = min(res, pl.price + solve(ns));
    }
    return res;
}

int main() {
    pw6[0] = 1;
    for (int i = 1; i <= 5; i++) pw6[i] = pw6[i - 1] * 6;

    int s;
    cin >> s;
    for (int i = 0; i < s; i++) {
        int n, p;
        cin >> n >> p;
        vector<pair<int, int>> items;
        for (int j = 0; j < n; j++) {
            int c, k;
            cin >> c >> k;
            items.push_back({c, k});
        }
        plans.push_back({items, p});
    }

    int b;
    cin >> b;
    int slot[1000];
    fill(slot, slot + 1000, -1);
    have = 0;
    for (int i = 0; i < b; i++) {
        int c, k, p;
        cin >> c >> k >> p;
        if (slot[c] == -1) slot[c] = have++;
        need[slot[c]] = k;
        price[slot[c]] = p;
    }

    // 丢弃含有清单外商品的方案
    vector<Plan> keep;
    for (auto &pl : plans) {
        bool ok = true;
        for (auto &it : pl.items) if (slot[it.first] == -1) { ok = false; break; }
        if (!ok) continue;
        Plan np;
        np.price = pl.price;
        for (auto &it : pl.items) np.items.push_back({slot[it.first], it.second});
        keep.push_back(np);
    }
    plans = keep;

    int start = 0;
    for (int i = 0; i < have; i++) start += need[i] * pw6[i];

    fill(memo, memo + 7776, -1);
    cout << solve(start) << endl;
    return 0;
}
